-- Forward-only: legacy treasury and campaign data are retained, never reused as creator orders.
SET LOCAL search_path=airtime,public;
CREATE TABLE platform_users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE platform_wallets(wallet text PRIMARY KEY,user_id uuid NOT NULL REFERENCES platform_users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE wallet_auth_challenges(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),wallet text NOT NULL,nonce text NOT NULL UNIQUE,message text NOT NULL,issued_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL,used_at timestamptz);
CREATE TABLE creator_sessions(token_hash text PRIMARY KEY,user_id uuid NOT NULL REFERENCES platform_users(id),wallet text NOT NULL REFERENCES platform_wallets(wallet),expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE platform_coins(mint text PRIMARY KEY,name text NOT NULL,ticker text NOT NULL,image_url text,metadata_source text NOT NULL DEFAULT 'CREATOR_SUPPLIED',market_cap_usd_cents bigint,current_creator text NOT NULL,venue text NOT NULL,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE coin_authorities(user_id uuid NOT NULL REFERENCES platform_users(id),mint text NOT NULL REFERENCES platform_coins(mint),wallet text NOT NULL REFERENCES platform_wallets(wallet),role text NOT NULL CHECK(role IN ('CREATOR','FEE_RECIPIENT','FEE_ADMIN')),evidence jsonb NOT NULL,verified_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,mint));
CREATE TABLE ad_campaigns(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES platform_users(id),mint text NOT NULL REFERENCES platform_coins(mint),title text NOT NULL,brief jsonb NOT NULL DEFAULT '{}',status text NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','AWAITING_PAYMENT','PAYMENT_VERIFYING','PAID','COMPLIANCE_REVIEW','CHANGES_REQUESTED','APPROVED','SCHEDULING','SCHEDULED','LIVE','COMPLETED','REJECTED','REFUND_PENDING','REFUNDED')),media_budget_cents bigint NOT NULL CHECK(media_budget_cents>0),duration_days int NOT NULL CHECK(duration_days BETWEEN 1 AND 90),proposed_start date NOT NULL,submitted_at timestamptz,external_platform text,external_campaign_id text,actual_start timestamptz,actual_end timestamptz,media_spend_cents bigint NOT NULL DEFAULT 0 CHECK(media_spend_cents>=0),platform_cost_cents bigint NOT NULL DEFAULT 0 CHECK(platform_cost_cents>=0),approval_proof_url text,placement_proof_url text,public_proof boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK(actual_end IS NULL OR (actual_start IS NOT NULL AND actual_end>actual_start)),UNIQUE(id,user_id));
CREATE TABLE campaign_creatives(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES platform_users(id),campaign_id uuid,object_path text NOT NULL UNIQUE,thumbnail_path text,original_name text NOT NULL,mime text NOT NULL,bytes bigint NOT NULL CHECK(bytes>0),metadata jsonb NOT NULL,validation_status text NOT NULL CHECK(validation_status IN ('TECHNICALLY_VALID','REJECTED')),created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(campaign_id,user_id) REFERENCES ad_campaigns(id,user_id),UNIQUE(id,user_id));
CREATE TABLE campaign_targeting(campaign_id uuid PRIMARY KEY REFERENCES ad_campaigns(id),selection jsonb NOT NULL,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE campaign_invoices(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),campaign_id uuid NOT NULL,user_id uuid NOT NULL,creator_wallet text NOT NULL,mint text NOT NULL,recipient_wallet text NOT NULL,media_budget_cents bigint NOT NULL CHECK(media_budget_cents>0),platform_fee_bps int NOT NULL CHECK(platform_fee_bps BETWEEN 0 AND 10000),platform_fee_cents bigint NOT NULL CHECK(platform_fee_cents>=0),total_usd_cents bigint NOT NULL CHECK(total_usd_cents=media_budget_cents+platform_fee_cents),price_usd_micros bigint NOT NULL CHECK(price_usd_micros>0),price_source text NOT NULL,price_fetched_at timestamptz NOT NULL,required_lamports bigint NOT NULL CHECK(required_lamports>0),expires_at timestamptz NOT NULL,status text NOT NULL DEFAULT 'OPEN' CHECK(status IN ('OPEN','VERIFYING','PAID','EXPIRED','CANCELLED')),refund_status text NOT NULL DEFAULT 'NONE' CHECK(refund_status IN ('NONE','PENDING','VERIFIED')),prepared_message text,prepared_blockheight bigint,prepared_at timestamptz,broadcast_signature text UNIQUE,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(campaign_id,user_id) REFERENCES ad_campaigns(id,user_id),UNIQUE(id,user_id),CHECK(platform_fee_cents=floor(media_budget_cents::numeric*platform_fee_bps/10000)),CHECK(required_lamports=ceil(total_usd_cents::numeric*10000000000000/price_usd_micros)));
CREATE UNIQUE INDEX one_live_invoice ON campaign_invoices(campaign_id) WHERE status IN ('OPEN','VERIFYING','PAID');
CREATE TABLE campaign_payments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),invoice_id uuid NOT NULL UNIQUE REFERENCES campaign_invoices(id),signature text NOT NULL UNIQUE,creator_wallet text NOT NULL,recipient_wallet text NOT NULL,amount_lamports bigint NOT NULL CHECK(amount_lamports>0),status text NOT NULL CHECK(status='FINALIZED'),slot bigint NOT NULL,block_time timestamptz NOT NULL,evidence jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE campaign_status_history(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),campaign_id uuid NOT NULL REFERENCES ad_campaigns(id),from_status text,to_status text NOT NULL,actor text NOT NULL,note text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE campaign_metrics(campaign_id uuid PRIMARY KEY REFERENCES ad_campaigns(id),impressions bigint NOT NULL DEFAULT 0 CHECK(impressions>=0),reach bigint NOT NULL DEFAULT 0 CHECK(reach>=0),cpm_cents bigint CHECK(cpm_cents>=0),source text NOT NULL DEFAULT 'ADMIN_ENTERED',updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE campaign_reviews(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),campaign_id uuid NOT NULL REFERENCES ad_campaigns(id),admin_id uuid NOT NULL REFERENCES admin_users(id),decision text NOT NULL,checklist jsonb NOT NULL,note text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE campaign_refunds(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),invoice_id uuid NOT NULL UNIQUE REFERENCES campaign_invoices(id),campaign_id uuid NOT NULL REFERENCES ad_campaigns(id),amount_lamports bigint NOT NULL CHECK(amount_lamports>0),reason text NOT NULL,status text NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','VERIFYING','VERIFIED','FAILED')),signature text UNIQUE,evidence jsonb,created_at timestamptz NOT NULL DEFAULT now(),confirmed_at timestamptz);
CREATE TABLE creator_messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),campaign_id uuid NOT NULL REFERENCES ad_campaigns(id),sender text NOT NULL,body text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE fee_claim_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES platform_users(id),wallet text NOT NULL,mint text NOT NULL REFERENCES platform_coins(mint),venue text NOT NULL,creator text NOT NULL,prepared_message text NOT NULL,blockheight bigint NOT NULL,signature text UNIQUE,status text NOT NULL DEFAULT 'PREPARED' CHECK(status IN ('PREPARED','BROADCAST','FINALIZED','FAILED')),exact_claim_lamports bigint,evidence jsonb,slot bigint,created_at timestamptz NOT NULL DEFAULT now(),confirmed_at timestamptz);
CREATE TABLE operations_audit(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),actor text NOT NULL,action text NOT NULL,entity_id text NOT NULL,details jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX creator_campaign_list ON ad_campaigns(user_id,created_at DESC);
CREATE INDEX creator_invoices ON campaign_invoices(user_id,created_at DESC);
CREATE INDEX creator_uploads ON campaign_creatives(user_id,created_at DESC);
CREATE INDEX creator_messages_order ON creator_messages(campaign_id,created_at);
CREATE INDEX wallet_challenge_expiry ON wallet_auth_challenges(expires_at);
CREATE INDEX creator_session_expiry ON creator_sessions(expires_at);
CREATE FUNCTION platform_no_delete() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Financial and audit records are immutable'; END $$;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['campaign_payments','campaign_status_history','campaign_reviews','operations_audit'] LOOP EXECUTE format('CREATE TRIGGER immutable_%I BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION platform_no_delete()',t,t); END LOOP; END $$;
CREATE FUNCTION platform_payment_guard() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE i campaign_invoices; BEGIN SELECT * INTO i FROM campaign_invoices WHERE id=NEW.invoice_id FOR UPDATE; IF i.status NOT IN ('OPEN','VERIFYING') OR NEW.creator_wallet<>i.creator_wallet OR NEW.recipient_wallet<>i.recipient_wallet OR NEW.amount_lamports<>i.required_lamports OR NEW.block_time<date_trunc('second',i.created_at) OR NEW.block_time>i.expires_at THEN RAISE EXCEPTION 'Payment does not match valid invoice'; END IF; RETURN NEW; END $$;
CREATE TRIGGER exact_invoice_payment BEFORE INSERT ON campaign_payments FOR EACH ROW EXECUTE FUNCTION platform_payment_guard();
CREATE FUNCTION platform_refund_guard() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE paid bigint; BEGIN SELECT amount_lamports INTO paid FROM campaign_payments WHERE invoice_id=NEW.invoice_id; IF paid IS NULL OR NEW.amount_lamports>paid THEN RAISE EXCEPTION 'Refund exceeds finalized payment'; END IF; IF TG_OP='UPDATE' AND OLD.status='VERIFIED' THEN RAISE EXCEPTION 'Verified refund is immutable'; END IF; RETURN NEW; END $$;
CREATE TRIGGER valid_invoice_refund BEFORE INSERT OR UPDATE ON campaign_refunds FOR EACH ROW EXECUTE FUNCTION platform_refund_guard();
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['platform_users','platform_wallets','wallet_auth_challenges','creator_sessions','platform_coins','coin_authorities','ad_campaigns','campaign_creatives','campaign_targeting','campaign_invoices','campaign_payments','campaign_status_history','campaign_metrics','campaign_reviews','campaign_refunds','creator_messages','fee_claim_requests','operations_audit'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('REVOKE ALL ON %I FROM PUBLIC',t); END LOOP; END $$;
CREATE TABLE platform_proofs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),campaign_id uuid NOT NULL REFERENCES ad_campaigns(id),kind text NOT NULL CHECK(kind IN ('APPROVAL','PLACEMENT','RECEIPT')),object_path text NOT NULL UNIQUE,mime text NOT NULL,original_name text NOT NULL,admin_id uuid NOT NULL REFERENCES admin_users(id),created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE platform_proofs ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON platform_proofs FROM PUBLIC;
CREATE FUNCTION platform_invoice_immutable() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.creator_wallet<>OLD.creator_wallet OR NEW.recipient_wallet<>OLD.recipient_wallet OR NEW.required_lamports<>OLD.required_lamports OR NEW.total_usd_cents<>OLD.total_usd_cents OR NEW.media_budget_cents<>OLD.media_budget_cents OR NEW.platform_fee_cents<>OLD.platform_fee_cents OR NEW.price_usd_micros<>OLD.price_usd_micros OR NEW.expires_at<>OLD.expires_at OR NEW.user_id<>OLD.user_id OR NEW.campaign_id<>OLD.campaign_id OR NEW.mint<>OLD.mint OR NEW.platform_fee_bps<>OLD.platform_fee_bps THEN RAISE EXCEPTION 'Invoice quote is immutable'; END IF; RETURN NEW; END $$;
CREATE TRIGGER immutable_invoice_quote BEFORE UPDATE ON campaign_invoices FOR EACH ROW EXECUTE FUNCTION platform_invoice_immutable();
